  const base = 'http://localhost:55955/card.html?size=';
  const dir = '/private/var/folders/hf/35wnqrnj2bbb1_llbg87zlt40000gn/T/vs-f6b521f2931aa9ab/';
  const sizes = [['square',1080,1080],['landscape',1920,1080],['story',1080,1920]];
  const out = [];
  for (const [name,w,h] of sizes){
    await page.setViewportSize({width:w, height:h});
