      const t=document.getElementById('title');
      const w2=t.parentElement;
      const card=document.getElementById('card');
      const r=[];
      document.querySelectorAll('.brand,.person,.titleWrap,.footer,.meta,.btn,.avatar,.who .name,.who .role,.main').forEach(e=>{
        const b=e.getBoundingClientRect();
        r.push(e.className+': '+Math.round(b.left)+','+Math.round(b.top)+' '+Math.round(b.width)+'x'+Math.round(b.height));
      });
      return {titleFS:getComputedStyle(t).fontSize, titleSH:t.scrollHeight, wrapCH:w2.clientHeight,
        cardScroll: card.scrollWidth+'x'+card.scrollHeight, rects:r};
    });
    out.push(name+' -> '+JSON.stringify(info,null,1));
  }
  return out.join('\n\n');
}

