        titleBox:[Math.round(w2.getBoundingClientRect().top),Math.round(w2.getBoundingClientRect().bottom)],
        titleSH:t.scrollHeight, wrapCH:w2.clientHeight,
        avatar:Math.round(av.width)+'x'+Math.round(av.height),
        nameH:Math.round(nm.height), problems:bad};
      function cssfs(el){return getComputedStyle(el).fontSize;}
    });
    out.push(name+' -> '+JSON.stringify(info));
  }
  return out.join('\n\n');
}

