      const t=document.getElementById('title'), wr=t.parentElement;
      const vw=innerWidth, vh=innerHeight, bad=[];
      document.querySelectorAll('.card *').forEach(e=>{
        const b=e.getBoundingClientRect();
        if(!b.width&&!b.height) return;
        if(b.left<-0.5||b.top<-0.5||b.right>vw+0.5||b.bottom>vh+0.5) bad.push('OUT '+e.className);
      });
      // pairwise overlap of major blocks
      const keys=['.brand','.person','.titleWrap','.footer'];
      const rs=keys.filter(k=>document.querySelector(k)).map(k=>[k,document.querySelector(k).getBoundingClientRect()]);
      for(let i=0;i<rs.length;i++)for(let j=i+1;j<rs.length;j++){
        const a=rs[i][1],b=rs[j][1];
        if(a.left<b.right&&b.left<a.right&&a.top<b.bottom&&b.top<a.bottom) bad.push('OVERLAP '+rs[i][0]+'/'+rs[j][0]);
      }
      const av=document.querySelector('.avatar'),cs=getComputedStyle(av),ab=av.getBoundingClientRect();
      return {fs:getComputedStyle(t).fontSize, titleFitsBy: wr.clientHeight-t.scrollHeight,
        circle:Math.round(ab.width)+'x'+Math.round(ab.height)+' r='+cs.borderRadius, problems:bad};
    });
    out.push(name+' '+JSON.stringify(info));
  }
  // verify saved PNG pixel dimensions
  const dims = [];
  for (const [name] of sizes){
    await page.setViewportSize({width:400,height:300});
    await page.goto('http://localhost:55955/'+name+'.png');
    const d = await page.evaluate(()=>{const i=document.querySelector('img');return i.naturalWidth+'x'+i.naturalHeight;});
    dims.push(name+'.png = '+d);
  }
  return out.join('\n')+'\n'+dims.join('\n');
}

